const raw = $json.body ? $json.body : $json;
let inputPayload = {};
if (raw.payload && typeof raw.payload === 'object') {
  inputPayload = raw.payload;
} else if (raw.body && raw.body.payload && typeof raw.body.payload === 'object') {
  inputPayload = raw.body.payload;
}
const daysNum = Number(inputPayload.days || raw.days || 30);
const days = Math.max(1, Math.min(90, daysNum || 30));
const requestId = String(raw.request_id || raw.requestId || ('dsu-' + Date.now()));
const dbPassword = inputPayload.auditPassword || raw.auditPassword || ($vars && $vars.DS_AUDIT_DB_PASSWORD) || '';

function shellQuote(value) {
  return "'" + String(value).replace(/'/g, "'\\''") + "'";
}
function sqlQuote(value) {
  return "'" + String(value).replace(/\\/g, '\\\\').replace(/'/g, "''") + "'";
}

const sql = [
  'SELECT request_id, trace_id, `operator`, source_system, country, action, target_type,',
  'project_code, workflow_code, workflow_name, instance_id, success, error_code, risk_level,',
  'duration_ms, operation_time,',
  'JSON_UNQUOTE(JSON_EXTRACT(request_payload, \'$.ds_token\')) AS token',
  'FROM `ds_operation_audit_log`',
  'WHERE operation_time >= DATE_SUB(NOW(), INTERVAL ' + days + ' DAY)',
  'ORDER BY operation_time ASC'
].join(' ');

const errors = [];
if (!dbPassword) errors.push('missing audit db password (DS_AUDIT_DB_PASSWORD)');
if (!sql.trim()) errors.push('sql is required');

if (errors.length) {
  return [{ json: { valid: false, errors: errors, requestId: requestId, days: days } }];
}

const meta = JSON.stringify({ requestId: requestId, days: days });
const remoteScript = [
  'set -euo pipefail',
  "printf '%s\\n' " + shellQuote('__DSU_META__' + meta),
  'MYSQL_PWD=' + shellQuote(dbPassword) + ' mysql --batch --raw --column-names ' +
    '--host=' + shellQuote('10.20.47.19') + ' --port=3306 --user=' + shellQuote('root') + ' ' +
    '--default-character-set=utf8mb4 ' + shellQuote('warning_rule') + ' -e ' + shellQuote(sql)
].join('\n');

return [{ json: { valid: true, command: remoteScript, requestId: requestId, days: days } }];

const raw = $json;
const stdout = String(raw.stdout || raw.data || '');
const stderr = String((raw.error && raw.error.message) || raw.stderr || '').trim();
const exitCode = (raw.code !== undefined && raw.code !== null) ? raw.code : ((raw.exitCode !== undefined && raw.exitCode !== null) ? raw.exitCode : (raw.error ? 1 : 0));

function parseValue(value) {
  if (value === undefined || value === null || value === 'NULL') return null;
  if (/^-?\d+(?:\.\d+)?$/.test(value)) {
    const n = Number(value);
    if (Number.isFinite(n)) return n;
  }
  return value;
}

const lines = stdout.split(/\r?\n/).filter(function (line) { return line.length > 0; });
let meta = {};
if (lines.length && lines[0].indexOf('__DSU_META__') === 0) {
  try {
    meta = JSON.parse(lines.shift().replace('__DSU_META__', ''));
  } catch (e) {}
}
const requestId = meta.requestId || '';
const days = meta.days || 0;

if (Number(exitCode) !== 0) {
  return [{ json: { success: false, requestId: requestId, days: days, rows: [], rowCount: 0, error: { code: 'COMMAND_FAILED', message: stderr || 'ssh/mysql command failed', exit_code: exitCode } } }];
}

if (!lines.length) {
  return [{ json: { success: true, requestId: requestId, days: days, rows: [], rowCount: 0 } }];
}

const headers = lines[0].split('\t');
const rows = lines.slice(1).map(function (line) {
  const values = line.split('\t');
  const row = {};
  for (let index = 0; index < headers.length; index++) {
    row[headers[index]] = parseValue(values[index]);
  }
  return row;
});

return [{ json: { success: true, requestId: requestId, days: days, rows: rows, rowCount: rows.length } }];

const raw = $json;
const errors = Array.isArray(raw.errors) ? raw.errors : ['invalid request'];
return [{
  json: {
    success: false,
    requestId: String(raw.requestId || raw.request_id || ''),
    days: Number(raw.days || 0),
    rows: [],
    rowCount: 0,
    error: { code: 'INVALID_REQUEST', message: errors.join('; ') || 'invalid request' },
  },
}];
